-- Fünf recherchierte Unternehmen; 25.11.2026.
-- Keine explizite BEGIN/COMMIT-Anweisung für DB Browser.
-- Bestehende Datensätze werden nicht überschrieben; Abgleich über exakten Namen.
-- Koordinaten nicht verifiziert, daher NULL. Klassifikationen sind KI-Zuordnungen.
PRAGMA foreign_keys = ON;
SAVEPOINT import_nrw_5;

-- Ford-Werke GmbH

-- HELLA GmbH & Co. KGaA

-- BPW Bergische Achsen KG

-- Brose Schließsysteme GmbH & Co. KG

-- TOYOTA RACING GmbH

RELEASE import_nrw_5;
PRAGMA foreign_key_check;
SELECT c.name,l.city,l.postal_code,l.address_line_1 FROM company c JOIN location l ON c.company_id=l.company_id WHERE c.name IN ('Ford-Werke GmbH','HELLA GmbH & Co. KGaA','BPW Bergische Achsen KG','Brose Schließsysteme GmbH & Co. KG','TOYOTA RACING GmbH') ORDER BY c.name;
